<dialog class="a00-modal" id="a00EditModal"><div class="a00-modal-bar"><strong id="a00EditTitle">Edit A00 — New Project Declaration</strong><button class="a00-modal-close" onclick="closeA00Edit()" aria-label="Tutup">&times;</button></div><iframe id="a00EditFrame" title="Edit A00 New Project Declaration"></iframe></dialog>
<dialog class="a00-confirm" id="a00DeleteModal"><div class="a00-confirm-head"><span class="a00-confirm-icon">!</span><span>Konfirmasi Hapus A00</span></div><div class="a00-confirm-body"><strong id="a00DeleteNumber"></strong><span>A00 beserta seluruh project dan workflow terkait akan dihapus permanen. Data yang sudah dihapus tidak dapat dikembalikan.</span></div><div class="a00-confirm-foot"><button class="a00-confirm-btn" id="cancelA00Delete" type="button">Batal</button><button class="a00-confirm-btn danger" id="confirmA00Delete" type="button">Ya, Hapus</button></div></dialog>
<script>
const a00Modal=document.getElementById('a00CreateModal'),a00Frame=document.getElementById('a00CreateFrame'),a00EditModal=document.getElementById('a00EditModal'),a00EditFrame=document.getElementById('a00EditFrame');
function openA00Modal(){if(!a00Frame.src)a00Frame.src=@json(route('control-project.a00.create',['embedded'=>1],false));a00Modal.showModal()}
function closeA00Modal(){a00Modal.close()}
function openA00Edit(data){a00EditFrame.src=data.url;document.getElementById('a00EditTitle').textContent='Edit A00 — '+data.number;a00EditModal.showModal()}
function closeA00Edit(){a00EditModal.close();a00EditFrame.src=''}
const a00DeleteModal=document.getElementById('a00DeleteModal'),a00DeleteNumber=document.getElementById('a00DeleteNumber');let pendingA00DeleteForm=null;
document.querySelectorAll('.a00-delete-form').forEach(form=>{form.removeAttribute('onsubmit');form.addEventListener('submit',event=>{event.preventDefault();pendingA00DeleteForm=form;const number=form.closest('tr').querySelector('td strong')?.textContent?.trim()||'A00 ini';a00DeleteNumber.textContent=number;a00DeleteModal.showModal()})});
document.getElementById('cancelA00Delete').addEventListener('click',()=>{pendingA00DeleteForm=null;a00DeleteModal.close()});
document.getElementById('confirmA00Delete').addEventListener('click',()=>{if(!pendingA00DeleteForm)return;const form=pendingA00DeleteForm;pendingA00DeleteForm=null;a00DeleteModal.close();form.submit()});
a00DeleteModal.addEventListener('click',event=>{if(event.target===a00DeleteModal){pendingA00DeleteForm=null;a00DeleteModal.close()}});
a00DeleteModal.addEventListener('close',()=>{pendingA00DeleteForm=null});
window.addEventListener('message',event=>{if(event.origin!==location.origin)return;if(event.data?.type==='a00-cancel')closeA00Modal();if(event.data?.type==='a00-created'){closeA00Modal();location.reload()}if(event.data?.type==='a00-edit-cancel')closeA00Edit();if(event.data?.type==='a00-updated'){closeA00Edit();location.reload()}});
</script>
